gC5(){return"\u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0645\u062e\u062a\u0648\u0645\u0629 (\u062a\u0645 \u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u062a\u0646\u0628\u064a\u0647)"},
gNd(){return"\u062a\u0645 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0631\u062d\u0644\u0629"},
gzT(){return"\u0627\u0644\u062a\u0642\u0637 \u0635\u0648\u0631\u0629 \u0625\u0630\u0627 \u0623\u0642\u0644\u0642\u0643 \u0645\u0648\u0642\u0641 \u0645\u0627 (\u0648\u062c\u0647\u060c \u0645\u0631\u0643\u0628\u0629\u060c \u0645\u0643\u0627\u0646\u2026). \u062a\u064f\u0648\u062f\u064e\u0639 \u0641\u064a \u062e\u0632\u0646\u0629 \u0645\u062e\u062a\u0648\u0645\u0629 \u0648\u0645\u0634\u0641\u0651\u0631\u0629: \u0644\u0627 \u0623\u062d\u062f \u064a\u0631\u0627\u0647\u0627\u060c \u0648\u0644\u0627 \u0623\u0646\u062a \u0646\u0641\u0633\u0643\u061b \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647\u0627 \u0625\u0644\u0627 \u0644\u0644\u0642\u0636\u0627\u0621 \u0628\u0645\u0648\u062c\u0628 \u0623\u0645\u0631 \u0642\u0636\u0627\u0626\u064a."},
gxv(){return"\u0631\u0645\u0632 \u0631\u0628\u0637 \u062c\u062f\u064a\u062f"},
