Cr(a){return"\u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0640 "+a},
gCS(){return"\u0628\u062f\u0621 \u0625\u062c\u0631\u0627\u0621"},
gzi(){return"\u062d\u0627\u0644\u0629 \u0627\u0644\u062d\u0645\u0627\u064a\u0629"},
