HE(a){return"\u0646\u0634\u0631 "+a+" \u0628\u0644\u0627\u063a \u0627\u0644\u0628\u062d\u062b"},
HK(a){return"\u0623\u063a\u0644\u0642 "+a+" \u0627\u0644\u0645\u0644\u0641"},
