gpO(){return"\u0639\u0627\u0645\u0644\u064a \u0627\u0644\u062b\u0627\u0646\u064a"},
grN(){return"\u0645\u0637\u0644\u0648\u0628 \u0644\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062d\u0633\u0651\u0627\u0633\u0629"},
gK6(){return"\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0627\u0644\u0642\u0648\u064a \u0645\u064f\u0641\u0639\u0651\u0644 \u0644\u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629"},
gK7(){return"\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0627\u0644\u0642\u0648\u064a \u063a\u064a\u0631 \u0645\u064f\u0641\u0639\u0651\u0644 \u0644\u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629"},
K9(a){return"\u062a\u0645\u0651 \u0627\u0644\u062a\u062d\u0642\u0642 \u0641\u064a "+a},
