gFo(){return"\u0627\u0644\u062f\u0639\u0648\u0629 \u062c\u0627\u0647\u0632\u0629"},
gFn(){return"\u0623\u0631\u0633\u0644 \u0647\u0630\u0627 \u0627\u0644\u0631\u0627\u0628\u0637 \u0625\u0644\u0649 \u0627\u0644\u0634\u062e\u0635. \u064a\u064f\u0639\u0631\u0636 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0635\u0627\u0644\u062d 14 \u064a\u0648\u0645\u064b\u0627."},
gFz(){return"\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0627\u0628\u0637"},
